NEXO.lei = [
{ art: "Art. 155", nome: "Furto", sec: "furto", itens: [
  { id:"155", rot:"caput", t:"<b class='g1'>Subtrair</b>, para si ou para outrem, <b class='g1'>coisa alheia móvel</b>:<br>Pena – reclusão, de <b class='g2'>1 (um) a 6 (seis) anos</b>, e multa.", nota:"Redação dada pela Lei nº 15.397, de 2026", novo:"Lei 15.397/2026", j:["stj-t934","stj-inf886","stj-inf887","stj-s567","stj-t1205","stf-insig"], c:["fc01","fc02","fc03","fc04"], q:["q-3adc"] },
  { id:"155-1", rot:"§ 1º", t:"A pena aumenta-se de <b class='g2'>metade</b>, se o crime é praticado durante o <b class='g1'>repouso noturno</b>.", nota:"Redação dada pela Lei nº 15.397, de 2026", novo:"Lei 15.397/2026", j:["stj-t1144","stj-t1087"], c:["fc05","fc06"], q:["q-3adc"] },
  { id:"155-2", rot:"§ 2º", t:"Se o criminoso é <b class='g3'>primário</b>, e é de <b class='g3'>pequeno valor</b> a coisa furtada, o juiz pode substituir a pena de reclusão pela de detenção, diminuí-la de <b class='g2'>um a dois terços</b>, ou aplicar somente a pena de multa.", j:["stj-s511","stj-jt47"], c:["fc07","fc08"] },
  { id:"155-3", rot:"§ 3º", t:"Equipara-se à coisa móvel a <b class='g1'>energia elétrica</b> ou qualquer outra que tenha <b class='g3'>valor econômico</b>.", j:["stj-energia","stj-tvcabo"], c:["fc09"] },
  { id:"155-4", rot:"§ 4º", t:"A pena é de reclusão, de <b class='g2'>2 (dois) a 8 (oito) anos</b>, e multa, se o crime é cometido:<br>I - com <b class='g1'>destruição ou rompimento de obstáculo</b> à subtração da coisa;<br>II - com <b class='g1'>abuso de confiança</b>, ou mediante <b class='g1'>fraude, escalada ou destreza</b>;<br>III - com emprego de <b class='g1'>chave falsa</b>;<br>IV - mediante concurso de <b class='g2'>duas ou mais</b> pessoas.<br>V – contra quaisquer bens que comprometam o funcionamento de órgãos da União, de Estado, do Distrito Federal ou de Município ou de estabelecimentos públicos ou privados que prestem <b class='g1'>serviços essenciais</b>.", nota:"Caput e inciso V com redação dada pela Lei nº 15.397, de 2026 (inciso V incluído pela Lei nº 15.181, de 2025)", novo:"Inciso V — Leis 15.181/2025 e 15.397/2026", j:["stj-s442","stj-s511","stj-jt47","stj-escalada","stj-t1107","stj-inf887"], c:["fc10","fc11","fc12","fc13"], q:["q-4f06"] },
  { id:"155-4A", rot:"§ 4º-A", t:"A pena é de reclusão de <b class='g2'>4 (quatro) a 10 (dez) anos</b> e multa, se houver emprego de <b class='g1'>explosivo</b> ou de artefato análogo que cause <b class='g3'>perigo comum</b>.", nota:"Incluído pela Lei nº 13.654, de 2018 — crime hediondo (Lei 8.072/90, art. 1º, IX)", c:["fc14","fc46"], q:["q-9ae5"] },
  { id:"155-4B", rot:"§ 4º-B", t:"A pena é de reclusão, de <b class='g2'>4 (quatro) a 10 (dez) anos</b>, e multa, se o furto mediante fraude é cometido por meio de <b class='g1'>dispositivo eletrônico ou informático</b>, conectado ou não à rede de computadores, com ou sem a violação de mecanismo de segurança ou a utilização de programa malicioso, ou por qualquer outro meio fraudulento análogo.", nota:"Redação dada pela Lei nº 15.397, de 2026", novo:"Pena máxima elevada — Lei 15.397/2026", c:["fc15","fc36"] },
  { id:"155-4C", rot:"§ 4º-C", t:"A pena prevista no § 4º-B deste artigo, considerada a relevância do resultado gravoso:<br>I – aumenta-se de <b class='g2'>1/3 (um terço) a 2/3 (dois terços)</b>, se o crime é praticado mediante a utilização de <b class='g1'>servidor mantido fora do território nacional</b>;<br>II – aumenta-se de <b class='g2'>1/3 (um terço) ao dobro</b>, se o crime é praticado contra <b class='g1'>idoso ou vulnerável</b>.", nota:"Incluído pela Lei nº 14.155, de 2021" },
  { id:"155-5", rot:"§ 5º", t:"A pena é de reclusão, de <b class='g2'>4 (quatro) a 10 (dez) anos</b>, e multa, se a subtração for de <b class='g1'>veículo automotor</b> que <b class='g3'>venha a ser transportado</b> para outro Estado ou para o exterior.", nota:"Redação dada pela Lei nº 15.397, de 2026", novo:"Lei 15.397/2026", c:["fc16"] },
  { id:"155-6", rot:"§ 6º", t:"A pena é de reclusão, de <b class='g2'>4 (quatro) a 10 (dez) anos</b>, e multa, se a subtração for:<br>I – de <b class='g1'>semovente domesticável de produção</b>, ainda que abatido ou dividido em partes no local da subtração, ou de <b class='g1'>animal doméstico</b>;<br>II – de <b class='g1'>aparelho de telefonia celular, de computador</b>, inclusive portátil ou do tipo prancheta, ou de qualquer dispositivo eletrônico ou informático semelhante.", nota:"Redação dada pela Lei nº 15.397, de 2026", novo:"Lei 15.397/2026", c:["fc17"] },
  { id:"155-7", rot:"§ 7º", t:"A pena é de reclusão, de <b class='g2'>4 (quatro) a 10 (dez) anos</b>, e multa, se a subtração for:<br>I – de <b class='g1'>substâncias explosivas</b> ou de acessórios que, conjunta ou isoladamente, possibilitem sua fabricação, montagem ou emprego;<br>II – de <b class='g1'>arma de fogo</b>.", nota:"Redação dada pela Lei nº 15.397, de 2026", novo:"Inciso II — Lei 15.397/2026", c:["fc18"] },
  { id:"155-8", rot:"§ 8º", t:"A pena é de reclusão, de <b class='g2'>2 (dois) a 8 (oito) anos</b>, e multa, se a subtração for de <b class='g1'>fios, cabos ou equipamentos</b> utilizados para fornecimento ou transmissão de energia elétrica ou de telefonia ou para transferência de dados, bem como equipamentos ou materiais <b class='g1'>ferroviários ou metroviários</b>, <b class='g3'>aplicável, em qualquer caso, o disposto no § 2º</b> deste artigo.", nota:"Incluído pela Lei nº 15.181, de 2025; redação dada pela Lei nº 15.397, de 2026", novo:"Leis 15.181/2025 e 15.397/2026", c:["fc19"], q:["q-4f06"] },
  { id:"155-9", rot:"§ 9º", t:"A pena é de reclusão de <b class='g2'>4 (quatro) a 10 (dez) anos</b> e multa, se a subtração, para si ou para outrem, de coisa alheia móvel é cometida por integrante de <b class='g1'>organização criminosa ultraviolenta, grupo paramilitar ou milícia privada</b>, <b class='g3'>no contexto da atuação</b> ou para a consecução das condutas previstas no art. 2º da lei que institui o marco legal do combate ao crime organizado no Brasil.", nota:"Incluído pela Lei nº 15.358, de 2026", novo:"Lei Antifacção — 15.358/2026", c:["fc20"] },
  { id:"155-10", rot:"§§ 10 a 12", t:"§ 10. A pena é de reclusão, de <b class='g2'>4 (quatro) a 10 (dez) anos</b>, e multa, se a subtração for de <b class='g1'>petróleo e derivados, gás natural</b> e suas frações recuperáveis, álcool etílico hidratado carburante e demais combustíveis fluidos carburantes, inclusive biocombustíveis, e óleos lubrificantes, <b class='g3'>removidos dos estabelecimentos de produção ou de quaisquer instalações de armazenamento e de transporte</b> de combustíveis, incluídos dutos e unidades de transporte em qualquer modal.<br>§ 11. Na hipótese do § 10, a pena é aumentada de <b class='g2'>1/3</b>, se o crime é praticado: I – com destruição, rompimento de obstáculo à subtração da coisa ou dano de qualquer natureza; II – mediante o concurso de 2 ou mais pessoas; III – com abuso de confiança ou valendo-se de vínculo atual ou passado com o ente lesado; ou IV – por ocupante de cargo, de emprego ou de função pública.<br>§ 12. Na hipótese do § 10, a pena é aumentada de <b class='g2'>2/3</b> se do crime resulta: I – suspensão ou paralisação das atividades do estabelecimento; II – desabastecimento; III – incêndio; IV – poluição efetiva ou potencial ao meio ambiente; V – lesão corporal grave; ou VI – morte.", nota:"Incluídos pela Lei nº 15.517, de 2026 (vigência em 23/09/2026)", novo:"Lei 15.517/2026", c:["fc21"] }
]},
{ art: "Art. 156", nome: "Furto de coisa comum", sec: "furto", itens: [
  { id:"156", rot:"caput e §§", t:"Subtrair o <b class='g1'>condômino, co-herdeiro ou sócio</b>, para si ou para outrem, a quem legitimamente a detém, a <b class='g1'>coisa comum</b>:<br>Pena - detenção, de <b class='g2'>seis meses a dois anos</b>, ou multa.<br>§ 1º - Somente se procede mediante <b class='g3'>representação</b>.<br>§ 2º - <b class='g3'>Não é punível</b> a subtração de coisa comum <b class='g1'>fungível</b>, cujo valor não excede a quota a que tem direito o agente.", c:["fc22"] }
]},
{ art: "Art. 157", nome: "Roubo", sec: "roubo", itens: [
  { id:"157", rot:"caput", t:"<b class='g1'>Subtrair</b> coisa móvel alheia, para si ou para outrem, mediante <b class='g1'>grave ameaça ou violência a pessoa</b>, ou depois de havê-la, por qualquer meio, <b class='g1'>reduzido à impossibilidade de resistência</b>:<br>Pena – reclusão, de <b class='g2'>6 (seis) a 10 (dez) anos</b>, e multa.", nota:"Redação dada pela Lei nº 15.397, de 2026", novo:"Lei 15.397/2026", j:["stj-s582","stj-t1192","stj-t1171"], c:["fc23","fc24"], q:["q-ef07"] },
  { id:"157-1", rot:"§ 1º", t:"Na mesma pena incorre quem, <b class='g3'>logo depois de subtraída a coisa</b>, emprega violência contra pessoa ou grave ameaça, a fim de assegurar a <b class='g1'>impunidade do crime ou a detenção da coisa</b> para si ou para terceiro.", c:["fc25"] },
  { id:"157-1A", rot:"§ 1º-A", t:"A pena é de reclusão, de <b class='g2'>6 (seis) a 12 (doze) anos</b>, e multa, se a subtração for cometida contra quaisquer bens que comprometam o funcionamento de órgãos da União, de Estado, do Distrito Federal ou de Município ou de estabelecimentos públicos ou privados que prestem <b class='g1'>serviços públicos essenciais</b>.", nota:"Incluído pela Lei nº 15.181, de 2025; redação dada pela Lei nº 15.397, de 2026", novo:"Leis 15.181/2025 e 15.397/2026" },
  { id:"157-2", rot:"§ 2º", t:"A pena aumenta-se de <b class='g2'>1/3 (um terço) até metade</b>:<br>I – (revogado);<br>II - se há o <b class='g1'>concurso de duas ou mais pessoas</b>;<br>III - se a vítima está em serviço de <b class='g1'>transporte de valores</b> e o agente <b class='g3'>conhece tal circunstância</b>;<br>IV - se a subtração for de veículo automotor que venha a ser transportado para outro Estado ou para o exterior;<br>V - se o agente mantém a vítima em seu poder, <b class='g1'>restringindo sua liberdade</b>;<br>VI – se a subtração for de substâncias explosivas ou de acessórios que, conjunta ou isoladamente, possibilitem sua fabricação, montagem ou emprego;<br>VII - se a violência ou grave ameaça é exercida com emprego de <b class='g1'>arma branca</b>;<br>VIII – se a subtração for de fios, cabos ou equipamentos utilizados para fornecimento ou transmissão de energia elétrica ou de telefonia ou para transferência de dados, bem como equipamentos ou materiais ferroviários ou metroviários;<br>IX – se a subtração for de <b class='g1'>aparelho de telefonia celular, de computador</b>, inclusive portátil ou do tipo prancheta, ou de qualquer dispositivo eletrônico ou informático semelhante;<br>X – se a subtração for de <b class='g1'>arma de fogo</b>;<br>XI – se a subtração for de petróleo e derivados, gás natural e suas frações recuperáveis, álcool etílico hidratado carburante e demais combustíveis fluidos carburantes, inclusive biocombustíveis, e óleos lubrificantes, removidos dos estabelecimentos de produção ou de quaisquer instalações de armazenamento e de transporte de combustíveis, incluídos dutos e unidades de transporte em qualquer modal.", nota:"Incisos VIII (Lei 15.181/2025), IX e X (Lei 15.397/2026) e XI (Lei 15.517/2026)", novo:"Incisos VIII a XI — 2025/2026", j:["stj-s443","stj-t1110"], c:["fc26","fc27","fc28"], q:["q-a688","q-ef07"] },
  { id:"157-2A", rot:"§ 2º-A", t:"A pena aumenta-se de <b class='g2'>2/3 (dois terços)</b>:<br>I – se a violência ou ameaça é exercida com emprego de <b class='g1'>arma de fogo</b>;<br>II – se há destruição ou rompimento de obstáculo mediante o emprego de <b class='g1'>explosivo</b> ou de artefato análogo que cause perigo comum.<br>III – se do crime previsto no inciso XI do § 2º deste artigo resulta: a) suspensão ou paralisação das atividades do estabelecimento; b) desabastecimento; c) incêndio; d) poluição efetiva ou potencial ao meio ambiente; ou e) (VETADO).", nota:"Incluído pela Lei nº 13.654, de 2018; inciso III pela Lei nº 15.517, de 2026", j:["stj-jt51","stj-t1407"], c:["fc29","fc30"] },
  { id:"157-2B", rot:"§ 2º-B", t:"Se a violência ou grave ameaça é exercida com emprego de arma de fogo de <b class='g1'>uso restrito ou proibido</b>, aplica-se <b class='g2'>em dobro</b> a pena prevista no caput deste artigo.", nota:"Incluído pela Lei nº 13.964, de 2019", c:["fc31"] },
  { id:"157-3", rot:"§ 3º", t:"Se <b class='g3'>da violência</b> resulta:<br>I – <b class='g1'>lesão corporal grave</b>, a pena é de reclusão de <b class='g2'>7 (sete) a 18 (dezoito) anos</b>, e multa;<br>II – <b class='g1'>morte</b>, a pena é de reclusão, de <b class='g2'>24 (vinte e quatro) a 30 (trinta) anos</b>, e multa.", nota:"Inciso II com redação dada pela Lei nº 15.397, de 2026", novo:"Latrocínio — Lei 15.397/2026", j:["stf-s610","stf-s603","stj-latro"], c:["fc32","fc33"] },
  { id:"157-4", rot:"§§ 4º e 5º", t:"§ 4º Se a violência ou grave ameaça é cometida por integrante de <b class='g1'>organização criminosa ultraviolenta, grupo paramilitar ou milícia privada</b>, <b class='g3'>no contexto da atuação</b> ou para a consecução das condutas previstas no art. 2º da lei que institui o marco legal do combate ao crime organizado no Brasil, aplica-se <b class='g2'>em triplo</b> a pena prevista no caput deste artigo, <b class='g3'>desprezadas as demais causas de aumento</b>.<br>§ 5º Se o crime previsto no inciso II do § 3º deste artigo é cometido por integrante de organização criminosa ultraviolenta, grupo paramilitar ou milícia privada, no contexto da atuação ou para a consecução das condutas previstas no art. 2º da lei que institui o marco legal do combate ao crime organizado no Brasil, e da violência resulta morte:<br>Pena - reclusão, de <b class='g2'>20 (vinte) a 40 (quarenta) anos</b>, e multa.", nota:"Incluídos pela Lei nº 15.358, de 2026", novo:"Lei Antifacção — 15.358/2026", c:["fc34"] }
]},
{ art: "Art. 158", nome: "Extorsão", sec: "extorsao", itens: [
  { id:"158", rot:"caput", t:"<b class='g1'>Constranger</b> alguém, mediante violência ou grave ameaça, e com o intuito de obter para si ou para outrem <b class='g1'>indevida vantagem econômica</b>, a <b class='g1'>fazer, tolerar que se faça ou deixar de fazer</b> alguma coisa:<br>Pena - reclusão, de <b class='g2'>quatro a dez anos</b>, e multa.", j:["stj-s96","stj-inf895"], c:["fc35","fc37"] },
  { id:"158-1", rot:"§§ 1º e 2º", t:"§ 1º - Se o crime é cometido por <b class='g1'>duas ou mais pessoas, ou com emprego de arma</b>, aumenta-se a pena de <b class='g2'>um terço até metade</b>.<br>§ 2º - Aplica-se à extorsão praticada mediante violência o disposto no § 3º do artigo anterior." },
  { id:"158-3", rot:"§ 3º", t:"Se o crime é cometido mediante a <b class='g1'>restrição da liberdade da vítima</b>, e <b class='g3'>essa condição é necessária</b> para a obtenção da vantagem econômica, a pena é de reclusão, de <b class='g2'>6 (seis) a 12 (doze) anos</b>, além da multa; se resulta lesão corporal grave ou morte, aplicam-se as penas previstas no art. 159, §§ 2º e 3º, respectivamente.", nota:"Incluído pela Lei nº 11.923, de 2009 — hediondo", c:["fc38"] },
  { id:"158-4", rot:"§ 4º", t:"Se os crimes previstos neste artigo são cometidos por integrante de organização criminosa, grupo paramilitar ou milícia privada, no contexto da atuação ou para a consecução das condutas previstas, aplica-se <b class='g2'>em triplo</b> a respectiva pena.", nota:"Incluído pela Lei nº 15.358, de 2026", novo:"Lei Antifacção — 15.358/2026" }
]},
{ art: "Art. 159", nome: "Extorsão mediante sequestro", sec: "extorsao", itens: [
  { id:"159", rot:"caput e §§", t:"<b class='g1'>Sequestrar pessoa</b> com o fim de obter, para si ou para outrem, qualquer vantagem, como <b class='g1'>condição ou preço do resgate</b>:<br>Pena - reclusão, de <b class='g2'>oito a quinze anos</b>.<br>§ 1º Se o sequestro dura mais de <b class='g2'>24 (vinte e quatro) horas</b>, se o sequestrado é <b class='g2'>menor de 18</b> (dezoito) ou <b class='g2'>maior de 60</b> (sessenta) anos, ou se o crime é cometido por bando ou quadrilha. Pena - reclusão, de <b class='g2'>doze a vinte anos</b>.<br>§ 2º - Se do fato resulta lesão corporal de natureza grave: Pena - reclusão, de <b class='g2'>dezesseis a vinte e quatro anos</b>.<br>§ 3º - Se resulta a morte: Pena - reclusão, de <b class='g2'>vinte e quatro a trinta anos</b>.<br>§ 4º - Se o crime é cometido em concurso, o concorrente que o <b class='g1'>denunciar à autoridade</b>, <b class='g3'>facilitando a libertação do sequestrado</b>, terá sua pena reduzida de <b class='g2'>um a dois terços</b>.<br>§ 5º Se os crimes previstos neste artigo são cometidos por integrante de organização criminosa ultraviolenta, grupo paramilitar ou milícia privada, no contexto da atuação (...), aumenta-se a respectiva pena em <b class='g2'>2/3 (dois terços)</b>.", nota:"§ 5º incluído pela Lei nº 15.358, de 2026 — todas as formas são hediondas", novo:"§ 5º — Lei 15.358/2026", c:["fc39","fc40"] }
]},
{ art: "Art. 160", nome: "Extorsão indireta", sec: "extorsao", itens: [
  { id:"160", rot:"caput", t:"<b class='g1'>Exigir ou receber</b>, como <b class='g1'>garantia de dívida</b>, abusando da situação de alguém, documento que pode dar causa a procedimento criminal contra a vítima ou contra terceiro:<br>Pena - reclusão, de <b class='g2'>um a três anos</b>, e multa." }
]},
{ art: "Arts. 161 a 167", nome: "Usurpação e dano", sec: "usurpacao-dano", itens: [
  { id:"161", rot:"Art. 161", t:"<b class='g1'>Suprimir ou deslocar</b> tapume, marco, ou qualquer outro sinal indicativo de linha divisória, para apropriar-se, no todo ou em parte, de coisa imóvel alheia: Pena - detenção, de <b class='g2'>um a seis meses</b>, e multa. § 1º - Na mesma pena incorre quem: I - desvia ou represa, em proveito próprio ou de outrem, águas alheias; II - invade, com violência a pessoa ou grave ameaça, ou mediante concurso de <b class='g2'>mais de duas pessoas</b>, terreno ou edifício alheio, para o fim de esbulho possessório. (...) § 3º - Se a propriedade é particular, e não há emprego de violência, <b class='g3'>somente se procede mediante queixa</b>.", c:["fc41"] },
  { id:"163", rot:"Art. 163", t:"<b class='g1'>Destruir, inutilizar ou deteriorar</b> coisa alheia: Pena - detenção, de <b class='g2'>um a seis meses</b>, ou multa.<br>Parágrafo único - Se o crime é cometido: I - com violência à pessoa ou grave ameaça; II - com emprego de substância inflamável ou explosiva, <b class='g3'>se o fato não constitui crime mais grave</b>; III - contra o patrimônio da União, de Estado, do Distrito Federal, de Município ou de autarquia, fundação pública, empresa pública, sociedade de economia mista ou empresa concessionária de serviços públicos; IV - por motivo egoístico ou com prejuízo considerável para a vítima: Pena - detenção, de <b class='g2'>seis meses a três anos</b>, e multa, além da pena correspondente à violência.", j:["stj-danopub"], c:["fc42"] },
  { id:"167", rot:"Art. 167", t:"Nos casos do art. 163, do inciso IV do seu parágrafo e do art. 164, <b class='g3'>somente se procede mediante queixa</b>.", c:["fc42"] }
]},
{ art: "Arts. 168 a 170", nome: "Apropriação indébita", sec: "apropriacao", itens: [
  { id:"168", rot:"Art. 168", t:"<b class='g1'>Apropriar-se</b> de coisa alheia móvel, <b class='g1'>de que tem a posse ou a detenção</b>: Pena - reclusão, de <b class='g2'>um a quatro anos</b>, e multa.<br>§ 1º - A pena é aumentada de <b class='g2'>um terço</b>, quando o agente recebeu a coisa: I - em depósito necessário; II - na qualidade de tutor, curador, síndico, liquidatário, inventariante, testamenteiro ou depositário judicial; III - em razão de ofício, emprego ou profissão.", c:["fc43"], q:["q-b3cb"] },
  { id:"168A", rot:"Art. 168-A", t:"<b class='g1'>Deixar de repassar</b> à previdência social as contribuições recolhidas dos contribuintes, no prazo e forma legal ou convencional: Pena – reclusão, de <b class='g2'>2 (dois) a 5 (cinco) anos</b>, e multa. (...)<br>§ 2º É <b class='g3'>extinta a punibilidade</b> se o agente, espontaneamente, declara, confessa e efetua o pagamento das contribuições, importâncias ou valores e presta as informações devidas à previdência social, na forma definida em lei ou regulamento, <b class='g3'>antes do início da ação fiscal</b>. (...)<br>§ 5º A extinção de punibilidade de que trata o § 2º deste artigo <b class='g3'>não se aplica ao agente declarado devedor contumaz</b> em decisão administrativa definitiva e inscrito no Cadastro Informativo dos créditos não quitados do setor público federal (Cadin) (...).<br>§ 6º O fato de o agente deixar de ser considerado devedor contumaz não afasta o disposto no § 5º deste artigo em relação aos atos praticados no período em que era assim considerado.", nota:"§§ 5º e 6º incluídos pela Lei Complementar nº 225, de 2026", novo:"LC 225/2026", j:["stj-t1166","stj-t1353"], c:["fc44"], q:["q-3349","q-1210"] },
  { id:"169", rot:"Arts. 169 e 170", t:"Art. 169 - Apropriar-se alguém de coisa alheia vinda ao seu poder por <b class='g1'>erro, caso fortuito ou força da natureza</b>: Pena - detenção, de <b class='g2'>um mês a um ano</b>, ou multa. Parágrafo único - Na mesma pena incorre: I - quem acha tesouro em prédio alheio e se apropria, no todo ou em parte, da quota a que tem direito o proprietário do prédio; II - quem <b class='g1'>acha coisa alheia perdida</b> e dela se apropria, total ou parcialmente, deixando de restituí-la ao dono ou legítimo possuidor ou de entregá-la à autoridade competente, dentro no prazo de <b class='g2'>15 (quinze) dias</b>.<br>Art. 170 - Nos crimes previstos neste Capítulo, aplica-se o disposto no <b class='g3'>art. 155, § 2º</b>.", c:["fc45"], q:["q-b3cb"] }
]},
{ art: "Art. 171", nome: "Estelionato", sec: "estelionato", itens: [
  { id:"171", rot:"caput e § 1º", t:"<b class='g1'>Obter</b>, para si ou para outrem, <b class='g1'>vantagem ilícita, em prejuízo alheio</b>, <b class='g1'>induzindo ou mantendo alguém em erro</b>, mediante artifício, ardil, ou qualquer outro meio fraudulento:<br>Pena – reclusão, de <b class='g2'>1 (um) a 5 (cinco) anos</b>, e multa.<br>§ 1º - Se o criminoso é <b class='g3'>primário</b>, e é de <b class='g3'>pequeno valor o prejuízo</b>, o juiz pode aplicar a pena conforme o disposto no art. 155, § 2º.", nota:"Pena com redação dada pela Lei nº 15.397, de 2026", j:["stj-s17","stj-s73","stj-jt84"], c:["fc47","fc48"], q:["q-3e08"] },
  { id:"171-2", rot:"§ 2º", t:"Nas mesmas penas incorre quem:<br>I - vende, permuta, dá em pagamento, em locação ou em garantia <b class='g1'>coisa alheia como própria</b>;<br>II - vende, permuta, dá em pagamento ou em garantia coisa própria inalienável, gravada de ônus ou litigiosa, ou imóvel que prometeu vender a terceiro, mediante pagamento em prestações, <b class='g3'>silenciando</b> sobre qualquer dessas circunstâncias;<br>III - defrauda, mediante alienação não consentida pelo credor ou por outro modo, a garantia pignoratícia, quando tem a posse do objeto empenhado;<br>IV - defrauda substância, qualidade ou quantidade de coisa que deve entregar a alguém;<br>V - destrói, total ou parcialmente, ou oculta coisa própria, ou lesa o próprio corpo ou a saúde, ou agrava as consequências da lesão ou doença, com o intuito de haver <b class='g1'>indenização ou valor de seguro</b>;<br>VI - emite <b class='g1'>cheque, sem suficiente provisão de fundos</b> em poder do sacado, ou lhe frustra o pagamento.<br>VII – <b class='g1'>cede</b>, gratuita ou onerosamente, <b class='g1'>conta bancária</b> para que nela transitem recursos destinados ao financiamento de atividade criminosa ou que dela sejam fruto.", nota:"Inciso VII incluído pela Lei nº 15.397, de 2026", novo:"Conta laranja — Lei 15.397/2026", j:["stf-s246","stf-s554"], c:["fc49","fc50","fc51"] },
  { id:"171-2A", rot:"§§ 2º-A e 2º-B", t:"§ 2º-A. A pena é de reclusão, de <b class='g2'>4 (quatro) a 8 (oito) anos</b>, e multa, se a fraude é cometida com a utilização de informações fornecidas pela vítima ou por terceiro induzido a erro por meio de <b class='g1'>redes sociais, contatos telefônicos, envio de correio eletrônico fraudulento, duplicação de dispositivo eletrônico ou aplicação de internet</b>, ou por qualquer outro meio fraudulento análogo.<br>§ 2º-B. A pena prevista no § 2º-A deste artigo, considerada a relevância do resultado gravoso, aumenta-se de <b class='g2'>1/3 (um terço) a 2/3 (dois terços)</b>, se o crime é praticado mediante a utilização de <b class='g1'>servidor mantido fora do território nacional</b>.", nota:"§ 2º-A com redação dada pela Lei nº 15.397, de 2026", novo:"Lei 15.397/2026", c:["fc36","fc52"] },
  { id:"171-3", rot:"§§ 3º e 4º", t:"§ 3º - A pena aumenta-se de <b class='g2'>um terço</b>, se o crime é cometido em detrimento de <b class='g1'>entidade de direito público</b> ou de instituto de economia popular, assistência social ou beneficência.<br>§ 4º A pena aumenta-se de <b class='g2'>1/3 (um terço) ao dobro</b>, se o crime é cometido contra <b class='g1'>idoso ou vulnerável</b>, considerada a relevância do resultado gravoso.", j:["stj-jt84"], c:["fc53"] },
  { id:"171-5", rot:"§ 5º (revogado)", t:"<s>§ 5º Somente se procede mediante representação, salvo se a vítima for: I - a Administração Pública, direta ou indireta; II - criança ou adolescente; III – pessoa com deficiência; ou IV - maior de 70 (setenta) anos de idade ou incapaz.</s>", nota:"Revogado pela Lei nº 15.397, de 2026 — a ação penal volta a ser pública incondicionada para fatos a partir de 04/05/2026", novo:"Revogado — Lei 15.397/2026", j:["stj-t1138"], c:["fc54"], q:["q-0c42"] }
]},
{ art: "Arts. 171-A e 176", nome: "Ativos virtuais e outras fraudes", sec: "estelionato", itens: [
  { id:"171A", rot:"Art. 171-A", t:"<b class='g1'>Organizar, gerir, ofertar ou distribuir carteiras ou intermediar operações</b> que envolvam <b class='g1'>ativos virtuais, valores mobiliários ou quaisquer ativos financeiros</b> com o fim de obter vantagem ilícita, em prejuízo alheio, induzindo ou mantendo alguém em erro, mediante artifício, ardil ou qualquer outro meio fraudulento.<br>Pena - reclusão, de <b class='g2'>4 (quatro) a 8 (oito) anos</b>, e multa.", nota:"Incluído pela Lei nº 14.478, de 2022", c:["fc55"] },
  { id:"176", rot:"Art. 176", t:"Tomar refeição em restaurante, alojar-se em hotel ou utilizar-se de meio de transporte <b class='g1'>sem dispor de recursos</b> para efetuar o pagamento: Pena - detenção, de <b class='g2'>quinze dias a dois meses</b>, ou multa. Parágrafo único - <b class='g3'>Somente se procede mediante representação</b>, e o juiz pode, conforme as circunstâncias, deixar de aplicar a pena." }
]},
{ art: "Art. 180", nome: "Receptação", sec: "receptacao", itens: [
  { id:"180", rot:"caput", t:"<b class='g1'>Adquirir, receber, transportar, conduzir ou ocultar</b>, em proveito próprio ou alheio, coisa que <b class='g1'>sabe</b> ser produto de crime, ou <b class='g1'>influir</b> para que terceiro, de boa-fé, a adquira, receba ou oculte:<br>Pena – reclusão, de <b class='g2'>2 (dois) a 6 (seis) anos</b>, e multa.", nota:"Pena com redação dada pela Lei nº 15.397, de 2026", novo:"Lei 15.397/2026", j:["stj-t1434"], c:["fc56","fc57"] },
  { id:"180-1", rot:"§§ 1º e 2º", t:"§ 1º - Adquirir, receber, transportar, conduzir, ocultar, ter em depósito, desmontar, montar, remontar, vender, expor à venda, ou de qualquer forma utilizar, em proveito próprio ou alheio, <b class='g1'>no exercício de atividade comercial ou industrial</b>, coisa que <b class='g1'>deve saber</b> ser produto de crime: Pena - reclusão, de <b class='g2'>três a oito anos</b>, e multa.<br>§ 2º - Equipara-se à atividade comercial, para efeito do parágrafo anterior, qualquer forma de <b class='g3'>comércio irregular ou clandestino, inclusive o exercício em residência</b>.", c:["fc58"] },
  { id:"180-3", rot:"§§ 3º a 5º", t:"§ 3º - Adquirir ou receber coisa que, por sua <b class='g1'>natureza</b> ou pela <b class='g1'>desproporção entre o valor e o preço</b>, ou pela <b class='g1'>condição de quem a oferece</b>, deve presumir-se obtida por meio criminoso: Pena - detenção, de <b class='g2'>um mês a um ano</b>, ou multa, ou ambas as penas.<br>§ 4º - A receptação é punível, <b class='g3'>ainda que desconhecido ou isento de pena o autor</b> do crime de que proveio a coisa.<br>§ 5º (Revogado).", nota:"§ 5º revogado pela Lei nº 15.358, de 2026", novo:"§ 5º revogado — 15.358/2026", c:["fc59"] },
  { id:"180-6", rot:"§§ 6º a 8º", t:"§ 6º Tratando-se de bens do patrimônio da União, de Estado, do Distrito Federal, de Município ou de autarquia, fundação pública, empresa pública, sociedade de economia mista ou empresa concessionária de serviços públicos, aplica-se <b class='g2'>em dobro</b> a pena prevista no caput deste artigo.<br>§ 7º Se a receptação for de fios, cabos ou equipamentos utilizados para fornecimento ou transmissão de energia elétrica ou de telefonia, transferência de dados, ou de cargas transportadas em modais logísticos ferroviários ou metroviários, aplica-se <b class='g2'>em dobro</b> a pena prevista no caput ou no § 1º deste artigo, conforme o caso.<br>§ 8º Se os crimes previstos neste artigo são cometidos por integrante de organização criminosa ultraviolenta, grupo paramilitar ou milícia privada, no contexto da atuação (...), aumenta-se a respectiva pena em <b class='g2'>2/3 (dois terços)</b>.", nota:"§ 7º incluído pela Lei nº 15.181, de 2025; § 8º pela Lei nº 15.358, de 2026", novo:"§§ 7º e 8º — 2025/2026" },
  { id:"180A", rot:"Art. 180-A", t:"Adquirir, receber, transportar, conduzir, ocultar, ter em depósito ou vender, <b class='g3'>com a finalidade de produção ou de comercialização</b>, semovente domesticável de produção, ainda que abatido ou dividido em partes, ou <b class='g1'>animal doméstico</b>, que <b class='g1'>sabe ou deve saber</b> ser produto de crime:<br>Pena – reclusão, de <b class='g2'>3 (três) a 8 (oito) anos</b>, e multa.", nota:"Redação dada pela Lei nº 15.397, de 2026", novo:"Lei 15.397/2026", c:["fc60"] }
]},
{ art: "Arts. 181 a 183-A", nome: "Disposições gerais", sec: "gerais", itens: [
  { id:"181", rot:"Art. 181", t:"É <b class='g1'>isento de pena</b> quem comete qualquer dos crimes previstos neste título, em prejuízo:<br>I - do <b class='g1'>cônjuge, na constância da sociedade conjugal</b>;<br>II - de <b class='g1'>ascendente ou descendente</b>, seja o parentesco legítimo ou ilegítimo, seja civil ou natural.", c:["fc61","fc62"] },
  { id:"182", rot:"Art. 182", t:"<b class='g3'>Somente se procede mediante representação</b>, se o crime previsto neste título é cometido em prejuízo:<br>I - do cônjuge desquitado ou judicialmente separado;<br>II - de <b class='g1'>irmão</b>, legítimo ou ilegítimo;<br>III - de <b class='g1'>tio ou sobrinho</b>, <b class='g3'>com quem o agente coabita</b>.", c:["fc62"] },
  { id:"183", rot:"Art. 183", t:"<b class='g3'>Não se aplica</b> o disposto nos dois artigos anteriores:<br>I - se o crime é de <b class='g1'>roubo ou de extorsão</b>, ou, em geral, quando haja emprego de <b class='g1'>grave ameaça ou violência à pessoa</b>;<br>II - ao <b class='g1'>estranho</b> que participa do crime.<br>III – se o crime é praticado contra pessoa com idade <b class='g2'>igual ou superior a 60 (sessenta) anos</b>.", c:["fc61","fc62"] },
  { id:"183A", rot:"Art. 183-A", t:"Nos crimes de que trata este Título, quando cometidos contra as <b class='g1'>instituições financeiras e os prestadores de serviço de segurança privada</b>, de que trata o Estatuto da Segurança Privada e da Segurança das Instituições Financeiras, as penas serão aumentadas de <b class='g2'>1/3 (um terço) até o dobro</b>.", nota:"Incluído pela Lei nº 14.967, de 2024", novo:"Lei 14.967/2024" }
]}
];

// Jurisprudência, flashcards e questões do piloto.
var STJ_TEMA = function(n){ return "https://processo.stj.jus.br/repetitivos/temas_repetitivos/pesquisa.jsp?novaConsulta=true&tipo_pesquisa=T&cod_tema_inicial="+n+"&cod_tema_final="+n; };
var STJ_SUM = "https://scon.stj.jus.br/SCON/sumanot/toc.jsp";
var STF_SUM = "https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=30";
var STJ_INF = function(n){ return "https://processo.stj.jus.br/jurisprudencia/externo/informativo/?acao=pesquisarumaedicao&livre=%27"+String(n).padStart(4,"0")+"%27.cod."; };

// status: vigente | atencao (lei nova ou ressalva) | divergencia | pendente (tema afetado, sem tese)
NEXO.juris = [
// ---------- FURTO ----------
{ id:"stj-t934", trib:"STJ", tipo:"Tema repetitivo", num:"934", sec:"furto", status:"vigente", data:"Julgado em 14/10/2015",
  titulo:"Consumação do furto — teoria da amotio",
  texto:"Consuma-se o crime de furto com a posse de fato da res furtiva, ainda que por breve espaço de tempo e seguida de perseguição ao agente, sendo prescindível a posse mansa e pacífica ou desvigiada.",
  explica:"Basta a inversão da posse. Perseguição e recuperação imediata não impedem a consumação.", lei:["155"], fonte:STJ_TEMA(934) },
{ id:"stj-inf886", trib:"STJ", tipo:"Informativo 886", num:"AgRg no AgRg no AREsp 3.063.890-MS", sec:"furto", status:"vigente", data:"5ª Turma, julgado em 03/03/2026",
  titulo:"Preso ainda dentro da loja, com os bens na mochila: tentativa",
  texto:"Ser surpreendido no interior do estabelecimento, com os bens acondicionados na mochila, revela apenas o caminho do crime, e não a inversão da posse — há tentativa de furto.",
  explica:"Aplicação prática do Tema 934 em lojas: a posse só se inverte quando o agente deixa o estabelecimento sem pagar.", lei:["155"], fonte:STJ_INF(886) },
{ id:"stj-inf887", trib:"STJ", tipo:"Informativo 887", num:"AgRg no REsp 2.255.737-MG", sec:"furto", status:"vigente", data:"Julgado em 07/04/2026",
  titulo:"Começar a romper o obstáculo já é tentativa",
  texto:"Quem inicia o rompimento de obstáculo e não consegue subtrair por circunstâncias alheias à sua vontade responde por tentativa de furto qualificado, e não por mero ato preparatório.",
  explica:"O início da execução pode ocorrer antes do verbo \"subtrair\", quando atos periféricos já atacam o bem jurídico (ex.: cadeado rompido, porta danificada).", lei:["155","155-4"], fonte:STJ_INF(887) },
{ id:"stj-s567", trib:"STJ", tipo:"Súmula", num:"567", sec:"furto", status:"vigente", data:"",
  titulo:"Vigilância não torna o furto impossível",
  texto:"Sistema de vigilância realizado por monitoramento eletrônico ou por existência de segurança no interior de estabelecimento comercial, por si só, não torna impossível a configuração do crime de furto.",
  explica:"A vigilância dificulta, mas não impede de forma absoluta a consumação — não é crime impossível (art. 17).", lei:["155"], fonte:STJ_SUM },
{ id:"stj-t1144", trib:"STJ", tipo:"Tema repetitivo", num:"1144", sec:"furto", status:"atencao", data:"Acórdão publicado em 27/06/2022",
  titulo:"O que é repouso noturno",
  texto:"O repouso noturno compreende o período em que a população se recolhe para descansar, conforme o caso concreto; são irrelevantes o fato de a vítima estar ou não dormindo e o local do crime (comércio, via pública, residência desabitada ou veículo), bastando que o furto ocorra à noite e em situação de repouso.",
  explica:"Atenção: o item 1 da tese fala em aumento de 1/3, mas a Lei 15.397/2026 mudou a fração para metade (fatos a partir de 04/05/2026).", lei:["155-1"], fonte:STJ_TEMA(1144) },
{ id:"stj-t1087", trib:"STJ", tipo:"Tema repetitivo", num:"1087", sec:"furto", status:"vigente", data:"Acórdão publicado em 27/06/2022",
  titulo:"Repouso noturno não incide no furto qualificado",
  texto:"A causa de aumento prevista no § 1° do art. 155 do Código Penal (prática do crime de furto no período noturno) não incide no crime de furto na sua forma qualificada (§ 4°).",
  explica:"Muito cobrado: noturno só majora o furto simples.", lei:["155-1","155-4"], fonte:STJ_TEMA(1087) },
{ id:"stj-s511", trib:"STJ", tipo:"Súmula", num:"511", sec:"furto", status:"vigente", data:"",
  titulo:"Furto qualificado-privilegiado",
  texto:"É possível o reconhecimento do privilégio previsto no § 2º do art. 155 do CP nos casos de crime de furto qualificado, se estiverem presentes a primariedade do agente, o pequeno valor da coisa e a qualificadora for de ordem objetiva.",
  explica:"Abuso de confiança é qualificadora subjetiva (afasta o privilégio); julgados recentes tratam a fraude também como subjetiva.", lei:["155-2","155-4"], fonte:STJ_SUM },
{ id:"stj-jt47", trib:"STJ", tipo:"Jurisprudência em Teses", num:"Ed. 47 e 221", sec:"furto", status:"vigente", data:"",
  titulo:"Pequeno valor, insignificância e qualificadoras",
  texto:"Pequeno valor é o que não excede 1 salário mínimo da época; a lesão não é insignificante, em regra, acima de 10% do salário mínimo; restituir o bem não gera privilégio; quebrar o vidro do carro para levar objetos internos qualifica; mixas são chave falsa; não há continuidade entre roubo e furto; em continuidade delitiva soma-se o valor dos bens.",
  explica:"Resumo das teses mais cobradas das edições 47 e 221.", lei:["155-2","155-4"], fonte:"https://scon.stj.jus.br/SCON/jt/" },
{ id:"stj-t1205", trib:"STJ", tipo:"Tema repetitivo", num:"1205", sec:"furto", status:"vigente", data:"Acórdão publicado em 30/10/2023",
  titulo:"Devolver o bem não basta para a insignificância",
  texto:"A restituição imediata e integral do bem furtado não constitui, por si só, motivo suficiente para a incidência do princípio da insignificância.",
  explica:"A insignificância exige os vetores do STF (mínima ofensividade, nenhuma periculosidade social, reduzido grau de reprovabilidade e inexpressividade da lesão).", lei:["155"], fonte:STJ_TEMA(1205) },
{ id:"stf-insig", trib:"STF/STJ", tipo:"Entendimento", num:"Reincidência e insignificância", sec:"furto", status:"divergencia", data:"STF Plenário (2015); STJ 5ª Turma, AREsp 3.043.521 (maio/2026)",
  titulo:"Reincidência não afasta automaticamente a insignificância",
  texto:"O Plenário do STF decidiu que a aplicação da insignificância ao reincidente deve ser analisada caso a caso. Em maio de 2026, a 5ª Turma do STJ, por maioria, aplicou a insignificância a réu reincidente no furto de três peças de queijo (R$ 66).",
  explica:"Não é pacífico: há votos vencidos e muitos julgados negando o benefício ao reincidente específico ou habitual. Em prova objetiva, prefira \"não se afasta automaticamente\".", lei:["155"], fonte:"https://www.migalhas.com.br/quentes/455792/stj-aplica-insignificancia-por-furto-de-queijos-a-reu-reincidente" },
{ id:"stj-s442", trib:"STJ", tipo:"Súmula", num:"442", sec:"furto", status:"vigente", data:"",
  titulo:"Sem majorante do roubo no furto",
  texto:"É inadmissível aplicar, no furto qualificado, pelo concurso de agentes, a majorante do roubo.",
  explica:"No furto, o concurso de pessoas é qualificadora (2 a 8 anos); não se troca por fração de aumento.", lei:["155-4"], fonte:STJ_SUM },
{ id:"stj-escalada", trib:"STJ", tipo:"Julgado", num:"AgRg no AREsp 2.703.772/DF", sec:"furto", status:"atencao", data:"6ª Turma, julgado em 18/02/2025",
  titulo:"Escalada presenciada por policiais dispensa perícia",
  texto:"É desnecessária a perícia para a qualificadora da escalada quando o iter criminis foi presenciado pelos policiais e não há versão defensiva em sentido contrário.",
  explica:"Regra geral (JT 47): escalada e rompimento exigem perícia, salvo vestígios desaparecidos ou impossibilidade. O tema está afetado como repetitivo (Tema 1107).", lei:["155-4"], fonte:"https://scon.stj.jus.br/SCON/" },
{ id:"stj-energia", trib:"STJ", tipo:"Julgados", num:"RHC 101.299/RS e outros", sec:"furto", status:"vigente", data:"",
  titulo:"Furto de energia: pagar não extingue a punibilidade",
  texto:"É inviável estender ao furto de energia elétrica a extinção da punibilidade pelo pagamento prevista para crimes tributários. \"Gato\" no poste é furto mediante fraude; adulterar o medidor para registrar consumo menor tem sido tratado como estelionato.",
  explica:"Diferença: no \"gato\" a energia é tirada; no medidor adulterado a concessionária é enganada e cobra menos.", lei:["155-3"], fonte:"https://scon.stj.jus.br/SCON/" },
{ id:"stj-tvcabo", trib:"STF/STJ", tipo:"Entendimento", num:"CC 173.968/SP (STJ)", sec:"furto", status:"vigente", data:"3ª Seção, julgado em 09/12/2020",
  titulo:"Sinal de TV a cabo: fato atípico",
  texto:"A captação clandestina de sinal de TV por assinatura não se equipara a furto de energia (vedação da analogia in malam partem).",
  explica:"STJ alinhou-se ao STF.", lei:["155-3"], fonte:"https://scon.stj.jus.br/SCON/" },
// ---------- ROUBO ----------
{ id:"stj-s582", trib:"STJ", tipo:"Súmula", num:"582 (Tema 916)", sec:"roubo", status:"vigente", data:"",
  titulo:"Consumação do roubo",
  texto:"Consuma-se o crime de roubo com a inversão da posse do bem mediante emprego de violência ou grave ameaça, ainda que por breve tempo e em seguida à perseguição imediata ao agente e recuperação da coisa roubada, sendo prescindível a posse mansa e pacífica ou desvigiada.",
  explica:"Mesma lógica do furto (amotio).", lei:["157"], fonte:STJ_SUM },
{ id:"stj-t1192", trib:"STJ", tipo:"Tema repetitivo", num:"1192", sec:"roubo", status:"vigente", data:"3ª Seção, julgado em 08/10/2025 (Inf. 868)",
  titulo:"Uma conduta, várias vítimas: concurso formal",
  texto:"Roubos praticados com uma única conduta, sem desígnios autônomos, contra o patrimônio de vítimas diferentes, ainda que da mesma família, configuram concurso formal de crimes (art. 70 do CP).",
  explica:"Cada patrimônio atingido é um crime; aplica-se a pena de um deles aumentada de 1/6 até metade.", lei:["157"], fonte:STJ_TEMA(1192) },
{ id:"stj-t1171", trib:"STJ", tipo:"Tema repetitivo", num:"1171", sec:"roubo", status:"vigente", data:"Acórdão publicado em 18/12/2023",
  titulo:"Simulacro de arma é grave ameaça",
  texto:"A utilização de simulacro de arma configura a elementar grave ameaça do tipo penal do roubo, subsumindo à hipótese legal que veda a substituição da pena.",
  explica:"Simulacro não gera a majorante da arma de fogo, mas mantém o roubo e impede a pena restritiva de direitos (art. 44, I).", lei:["157","157-2A"], fonte:STJ_TEMA(1171) },
{ id:"stj-s443", trib:"STJ", tipo:"Súmula", num:"443", sec:"roubo", status:"vigente", data:"",
  titulo:"Fração acima de 1/3 exige fundamentação concreta",
  texto:"O aumento na terceira fase de aplicação da pena no crime de roubo circunstanciado exige fundamentação concreta, não sendo suficiente para a sua exasperação a mera indicação do número de majorantes.",
  explica:"Duas majorantes, por si sós, não autorizam aumento de metade.", lei:["157-2"], fonte:STJ_SUM },
{ id:"stj-t1110", trib:"STJ", tipo:"Tema repetitivo", num:"1110", sec:"roubo", status:"vigente", data:"Acórdão publicado em 27/05/2022",
  titulo:"Arma branca no intervalo 2018–2020",
  texto:"Em razão da lei mais benéfica (Lei 13.654/2018), o emprego de arma branca, embora não configurasse causa de aumento, pode fundamentar a elevação da pena-base quando as circunstâncias do caso justificarem.",
  explica:"Vale para roubos com arma branca praticados antes de 23/01/2020. Depois disso, aplica-se o inciso VII.", lei:["157-2"], fonte:STJ_TEMA(1110) },
{ id:"stj-jt51", trib:"STJ", tipo:"Jurisprudência em Teses", num:"Ed. 51", sec:"roubo", status:"atencao", data:"",
  titulo:"Teses sobre arma de fogo no roubo",
  texto:"É prescindível a apreensão e perícia da arma de fogo quando o emprego for provado por outros meios; cabe à defesa provar que a arma não tinha potencial lesivo; arma sem potencial lesivo atestado por perícia caracteriza grave ameaça, mas não a majorante.",
  explica:"A exigência de apreensão ou perícia está afetada como repetitivo (Tema 1407) — acompanhe.", lei:["157-2A"], fonte:"https://scon.stj.jus.br/SCON/jt/" },
{ id:"stf-s610", trib:"STF", tipo:"Súmula", num:"610", sec:"roubo", status:"vigente", data:"",
  titulo:"Latrocínio consumado sem subtração",
  texto:"Há crime de latrocínio, quando o homicídio se consuma, ainda que não realize o agente a subtração de bens da vítima.",
  explica:"O resultado morte define a consumação.", lei:["157-3"], fonte:STF_SUM },
{ id:"stf-s603", trib:"STF", tipo:"Súmula", num:"603", sec:"roubo", status:"vigente", data:"",
  titulo:"Latrocínio é do juiz singular",
  texto:"A competência para o processo e julgamento de latrocínio é do juiz singular e não do Tribunal do Júri.",
  explica:"Latrocínio é crime contra o patrimônio, não crime doloso contra a vida.", lei:["157-3"], fonte:STF_SUM },
{ id:"stj-latro", trib:"STJ/STF", tipo:"Divergência", num:"AgRg no AREsp 2.119.185/RS × AgRg no HC 940.579/SP", sec:"roubo", status:"divergencia", data:"2023 e 2024",
  titulo:"Várias mortes e um só patrimônio",
  texto:"O STF tem reconhecido crime único de latrocínio quando apenas um patrimônio é atingido, ainda que haja várias mortes. O STJ já acompanhou o STF (2023), mas decisão posterior (2024) reafirmou o concurso formal impróprio.",
  explica:"Tema sem consenso — dificilmente cobrado de forma direta em prova objetiva de nível médio/superior policial.", lei:["157-3"], fonte:"https://scon.stj.jus.br/SCON/" },
// ---------- EXTORSÃO ----------
{ id:"stj-s96", trib:"STJ", tipo:"Súmula", num:"96", sec:"extorsao", status:"atencao", data:"",
  titulo:"Extorsão é crime formal",
  texto:"O crime de extorsão consuma-se independentemente da obtenção da vantagem indevida.",
  explica:"Leia junto com o EAREsp 2.819.893-SP (2026): é preciso ao menos um início de submissão da vítima.", lei:["158"], fonte:STJ_SUM },
{ id:"stj-inf895", trib:"STJ", tipo:"Informativo 895", num:"EAREsp 2.819.893-SP", sec:"extorsao", status:"vigente", data:"3ª Seção, julgado em 10/06/2026",
  titulo:"Extorsão admite tentativa sem submissão da vítima",
  texto:"O crime de extorsão, embora de natureza formal, admite a forma tentada quando, apesar da ameaça, a vítima não pratica qualquer conduta em decorrência do constrangimento.",
  explica:"Consumação exige um mínimo de resposta da vítima (fazer, tolerar ou deixar de fazer). Julgado pela Seção, uniformiza as Turmas.", lei:["158"], fonte:STJ_INF(895) },
// ---------- DANO ----------
{ id:"stj-danopub", trib:"STJ", tipo:"Jurisprudência em Teses", num:"Ed. 220, tese 10", sec:"usurpacao-dano", status:"vigente", data:"",
  titulo:"Sem insignificância no dano ao patrimônio público",
  texto:"Não é possível aplicar o princípio da insignificância ao crime de dano qualificado ao patrimônio público, diante da lesão a bem jurídico de relevante valor social.",
  explica:"", lei:["163"], fonte:"https://scon.stj.jus.br/SCON/jt/" },
// ---------- APROPRIAÇÃO ----------
{ id:"stj-t1166", trib:"STJ", tipo:"Tema repetitivo", num:"1166", sec:"apropriacao", status:"vigente", data:"Acórdão publicado em 20/10/2023",
  titulo:"Apropriação indébita previdenciária é crime material",
  texto:"O crime de apropriação indébita previdenciária, previsto no art. 168-A, § 1º, inciso I, do Código Penal, possui natureza de delito material, que só se consuma com a constituição definitiva, na via administrativa, do crédito tributário, consoante o disposto na Súmula Vinculante n. 24 do STF.",
  explica:"Cobrado pela Cebraspe na prova de Delegado da PF (2025).", lei:["168A"], fonte:STJ_TEMA(1166) },
{ id:"stj-t1353", trib:"STJ", tipo:"Tema repetitivo", num:"1353", sec:"apropriacao", status:"vigente", data:"3ª Seção, 10/06/2026",
  titulo:"Sem continuidade entre 168-A e 337-A",
  texto:"É inviável reconhecer a continuidade delitiva entre os delitos de apropriação indébita previdenciária (art. 168-A do CP) e de sonegação de contribuição previdenciária (art. 337-A do CP), por se tratarem de espécies diversas que descrevem condutas típicas distintas, embora sejam do mesmo gênero.",
  explica:"Aplica-se a regra geral do concurso de crimes.", lei:["168A"], fonte:STJ_TEMA(1353) },
// ---------- ESTELIONATO ----------
{ id:"stj-s17", trib:"STJ", tipo:"Súmula", num:"17", sec:"estelionato", status:"vigente", data:"",
  titulo:"Falso absorvido pelo estelionato",
  texto:"Quando o falso se exaure no estelionato, sem mais potencialidade lesiva, é por este absorvido.",
  explica:"Princípio da consunção: crime-meio absorvido pelo crime-fim.", lei:["171"], fonte:STJ_SUM },
{ id:"stj-s73", trib:"STJ", tipo:"Súmula", num:"73", sec:"estelionato", status:"vigente", data:"",
  titulo:"Moeda grosseiramente falsificada",
  texto:"A utilização de papel moeda grosseiramente falsificado configura, em tese, o crime de estelionato, da competência da Justiça Estadual.",
  explica:"Falsificação grosseira não engana o público em geral, então não é moeda falsa (crime federal), mas pode enganar a vítima concreta.", lei:["171"], fonte:STJ_SUM },
{ id:"stj-jt84", trib:"STJ", tipo:"Jurisprudência em Teses", num:"Ed. 84", sec:"estelionato", status:"vigente", data:"",
  titulo:"Estelionato previdenciário e reparação do dano",
  texto:"Estelionato previdenciário: permanente para o próprio beneficiário; instantâneo de efeitos permanentes para o terceiro; não admite insignificância; devolver o valor antes da denúncia não extingue a punibilidade. No estelionato comum, ressarcir o dano não extingue a punibilidade, salvo no cheque sem fundos pago antes da denúncia.",
  explica:"", lei:["171","171-3"], fonte:"https://scon.stj.jus.br/SCON/jt/" },
{ id:"stf-s246", trib:"STF", tipo:"Súmula", num:"246", sec:"estelionato", status:"vigente", data:"",
  titulo:"Cheque sem fundos exige fraude",
  texto:"Comprovado não ter havido fraude, não se configura o crime de emissão de cheque sem fundos.",
  explica:"Cheque pré-datado dado em garantia de dívida não é crime.", lei:["171-2"], fonte:STF_SUM },
{ id:"stf-s554", trib:"STF", tipo:"Súmula", num:"554", sec:"estelionato", status:"vigente", data:"",
  titulo:"Pagamento do cheque após a denúncia",
  texto:"O pagamento de cheque emitido sem provisão de fundos, após o recebimento da denúncia, não obsta ao prosseguimento da ação penal.",
  explica:"Leitura a contrario: pagar antes do recebimento da denúncia impede a ação penal.", lei:["171-2"], fonte:STF_SUM },
// ---------- PENDENTES (temas afetados, sem tese) ----------
{ id:"stj-t1107", trib:"STJ", tipo:"Tema afetado", num:"1107", sec:"furto", status:"pendente", data:"Afetado em 19/04/2026",
  titulo:"Laudo oficial no rompimento de obstáculo",
  texto:"Questão: se o laudo de perito oficial é indispensável para reconhecer a qualificadora do rompimento de obstáculo.",
  explica:"Ainda sem tese. Até lá, vale a regra geral: perícia, salvo vestígios desaparecidos ou impossibilidade.", lei:["155-4"], fonte:STJ_TEMA(1107) },
{ id:"stj-t1227", trib:"STJ", tipo:"Tema afetado", num:"1227", sec:"roubo", status:"pendente", data:"Afetado",
  titulo:"Violência contra a coisa configura roubo?",
  texto:"Questão: se a violência do roubo precisa ser dirigida à pessoa ou pode ser empregada contra um objeto (ex.: puxão da bolsa).",
  explica:"Ainda sem tese.", lei:["157"], fonte:STJ_TEMA(1227) },
{ id:"stj-t1407", trib:"STJ", tipo:"Tema afetado", num:"1407", sec:"roubo", status:"pendente", data:"Afetado em 11/02/2026",
  titulo:"Apreensão e perícia da arma de fogo",
  texto:"Questão: se é exigível a apreensão e/ou perícia da arma de fogo para a causa de aumento do art. 157, § 2º-A, I.",
  explica:"Ainda sem tese; prevalece a JT 51 (dispensa, se provado por outros meios).", lei:["157-2A"], fonte:STJ_TEMA(1407) },
{ id:"stj-t1434", trib:"STJ", tipo:"Tema afetado", num:"1434", sec:"receptacao", status:"pendente", data:"Afetado em 18/05/2026",
  titulo:"Ônus da prova na receptação",
  texto:"Questão: a quem cabe provar a origem lícita ou ilícita do bem apreendido em poder do acusado de receptação.",
  explica:"Ainda sem tese.", lei:["180"], fonte:STJ_TEMA(1434) },
{ id:"stj-t1138", trib:"STJ", tipo:"Tema", num:"1138", sec:"estelionato", status:"pendente", data:"Situação em 12/11/2025: tema mantido, recursos desafetados",
  titulo:"Retroatividade da representação no estelionato (2019)",
  texto:"Questão: alcance retroativo do § 5º do art. 171 (representação), incluído pela Lei 13.964/2019. STF admitia até o trânsito em julgado; STJ, só sem denúncia oferecida.",
  explica:"O § 5º foi revogado em 2026, mas o tema segue relevante para fatos de 23/01/2020 a 03/05/2026.", lei:["171-5"], fonte:STJ_TEMA(1138) }
];

// tipos: caso | numero | distincao | lacuna | ce | juris
NEXO.cards = [
{ id:"fc01", tipo:"caso", sec:"furto", f:"Ana coloca dois perfumes na mochila dentro da loja e é abordada pelo segurança antes de passar pelo caixa. Furto consumado ou tentado?", v:"<b>Tentado.</b> Ainda dentro do estabelecimento não houve inversão da posse (STJ, Informativo 886/2026).", lei:["155"], j:["stj-inf886"] },
{ id:"fc02", tipo:"juris", sec:"furto", f:"Tema 934: o furto exige posse mansa e pacífica para se consumar?", v:"<b>Não.</b> Basta a posse de fato, ainda que breve e com perseguição (teoria da amotio).", lei:["155"], j:["stj-t934"] },
{ id:"fc03", tipo:"ce", sec:"furto", f:"Certo ou errado: o monitoramento por câmeras e seguranças torna impossível o furto em supermercado.", v:"<b>Errado.</b> Súmula 567 do STJ: por si só, não torna impossível.", lei:["155"], j:["stj-s567"] },
{ id:"fc04", tipo:"distincao", sec:"furto", f:"Furto de uso × furto: qual a diferença e a consequência?", v:"No furto de uso falta a intenção de ficar com a coisa (usa e devolve logo, intacta) — <b>fato atípico</b>. No roubo de uso, porém, há crime.", lei:["155"] },
{ id:"fc05", tipo:"numero", sec:"furto", f:"Furto no repouso noturno: de quanto é o aumento?", v:"<b>Metade</b>, para fatos a partir de 04/05/2026 (Lei 15.397). Antes, era 1/3.", lei:["155-1"], j:["stj-t1144"] },
{ id:"fc06", tipo:"ce", sec:"furto", f:"Certo ou errado: o furto qualificado pelo rompimento de obstáculo, praticado de madrugada, recebe também o aumento do repouso noturno.", v:"<b>Errado.</b> Tema 1087: o § 1º não incide no furto qualificado.", lei:["155-1","155-4"], j:["stj-t1087"] },
{ id:"fc07", tipo:"numero", sec:"furto", f:"Qual o parâmetro de \"pequeno valor\" (privilégio) e de \"valor insignificante\" no furto?", v:"Pequeno valor: até <b>1 salário mínimo</b> da época. Insignificante: em regra, até <b>10% do salário mínimo</b>.", lei:["155-2"], j:["stj-jt47"] },
{ id:"fc08", tipo:"caso", sec:"furto", f:"Babá primária furta joia de R$ 300 aproveitando a confiança dos patrões. Cabe o privilégio?", v:"<b>Não.</b> Abuso de confiança é qualificadora subjetiva, incompatível com o privilégio (Súmula 511).", lei:["155-2","155-4"], j:["stj-s511"] },
{ id:"fc09", tipo:"distincao", sec:"furto", f:"\"Gato\" no poste × medidor adulterado para registrar menos consumo.", v:"\"Gato\": <b>furto</b> de energia (§ 3º). Medidor adulterado: a concessionária é enganada e cobra menos — tem prevalecido <b>estelionato</b>.", lei:["155-3"], j:["stj-energia"] },
{ id:"fc10", tipo:"caso", sec:"furto", f:"Quebrar o vidro do carro para levar o notebook do banco traseiro qualifica o furto? E quebrar o vidro para levar o próprio carro?", v:"Notebook: <b>sim</b>, rompimento de obstáculo. O carro: <b>não</b> — a violência foi contra a própria coisa furtada.", lei:["155-4"], j:["stj-jt47"] },
{ id:"fc11", tipo:"caso", sec:"furto", f:"Batedor de carteira é percebido pela vítima no momento em que enfia a mão na bolsa. Qual o crime?", v:"<b>Furto simples tentado.</b> Se foi percebido, não houve destreza.", lei:["155-4"] },
{ id:"fc12", tipo:"lacuna", sec:"furto", f:"Súmula 442 do STJ: \"É inadmissível aplicar, no furto qualificado, pelo ______, a majorante do roubo.\"", v:"<b>concurso de agentes</b>", lei:["155-4"], j:["stj-s442"] },
{ id:"fc13", tipo:"juris", sec:"furto", f:"Escalada e rompimento de obstáculo exigem perícia?", v:"<b>Em regra, sim</b>, salvo vestígios desaparecidos ou impossibilidade. Há julgado dispensando quando policiais presenciaram a escalada. O tema está afetado (Tema 1107).", lei:["155-4"], j:["stj-escalada","stj-t1107"] },
{ id:"fc14", tipo:"ce", sec:"gerais", f:"Certo ou errado: o furto qualificado pelo emprego de explosivo é crime hediondo.", v:"<b>Certo.</b> Lei 8.072/90, art. 1º, IX (art. 155, § 4º-A).", lei:["155-4A"] },
{ id:"fc15", tipo:"distincao", sec:"estelionato", f:"Furto eletrônico (155, § 4º-B) × fraude eletrônica (171, § 2º-A).", v:"Furto: o agente <b>tira</b> o dinheiro sem a vítima perceber (ex.: usa a senha capturada por vírus) — 4 a 10 anos. Fraude eletrônica: a vítima é enganada e <b>entrega/transfere</b> — 4 a 8 anos.", lei:["155-4B","171-2A"] },
{ id:"fc16", tipo:"caso", sec:"furto", f:"Ladrão furta um carro para levá-lo ao Paraguai, mas é preso ainda na mesma cidade. Furto qualificado tentado (§ 5º)?", v:"<b>Não.</b> Furto <b>consumado</b> (a subtração se completou), sem a qualificadora do § 5º, que exige o transporte efetivo.", lei:["155-5"] },
{ id:"fc17", tipo:"numero", sec:"furto", f:"Qual a pena do furto de celular para fatos a partir de 04/05/2026?", v:"<b>4 a 10 anos</b> e multa — qualificadora do art. 155, § 6º, II.", lei:["155-6"] },
{ id:"fc18", tipo:"distincao", sec:"roubo", f:"Arma de fogo: subtrair no furto × subtrair no roubo × empregar no roubo.", v:"Subtrair no furto: <b>qualificadora</b> (155, § 7º, II — 4 a 10). Subtrair no roubo: <b>majorante</b> de 1/3 a metade (157, § 2º, X). Empregar no roubo: <b>+2/3</b> (§ 2º-A, I) ou <b>dobro</b> se de uso restrito/proibido (§ 2º-B).", lei:["155-7","157-2","157-2A","157-2B"] },
{ id:"fc19", tipo:"lacuna", sec:"furto", f:"No furto de fios e cabos de energia (155, § 8º), a lei manda aplicar \"em qualquer caso\" o ______.", v:"<b>§ 2º — o privilégio</b> (réu primário e coisa de pequeno valor).", lei:["155-8"] },
{ id:"fc20", tipo:"ce", sec:"furto", f:"Certo ou errado: basta o agente ser integrante de facção criminosa para incidir a qualificadora do art. 155, § 9º.", v:"<b>Errado.</b> O furto precisa ocorrer no contexto da atuação do grupo ou para seus fins.", lei:["155-9"] },
{ id:"fc21", tipo:"caso", sec:"furto", f:"Furtar diesel do tanque de um caminhão comum estacionado configura a qualificadora do § 10 (combustíveis)?", v:"<b>Não.</b> O § 10 exige combustível retirado de instalações de produção, armazenamento ou transporte (ex.: carga de caminhão-tanque, duto). Tanque de abastecimento é furto comum.", lei:["155-10"] },
{ id:"fc22", tipo:"numero", sec:"furto", f:"Furto de coisa comum: qual a ação penal e quando não é punível?", v:"Ação <b>condicionada à representação</b>. Não é punível se a coisa é <b>fungível</b> e o valor não excede a cota do agente.", lei:["156"] },
{ id:"fc23", tipo:"juris", sec:"roubo", f:"Súmula 582: o roubo se consuma quando?", v:"Com a <b>inversão da posse</b> mediante violência ou grave ameaça, ainda que breve, com perseguição imediata e recuperação da coisa.", lei:["157"], j:["stj-s582"] },
{ id:"fc24", tipo:"caso", sec:"roubo", f:"Assaltante entra no ônibus e, com uma só ação, leva o celular de 5 passageiros. Quantos crimes?", v:"<b>5 roubos em concurso formal</b> (Tema 1192): uma conduta, patrimônios diferentes.", lei:["157"], j:["stj-t1192"] },
{ id:"fc25", tipo:"distincao", sec:"roubo", f:"Roubo próprio × impróprio. Embriagar a vítima depois de furtar gera roubo impróprio?", v:"Próprio: violência <b>antes/durante</b>, para subtrair (admite violência imprópria). Impróprio: violência <b>logo depois</b>, para garantir a coisa ou a impunidade — só violência real ou grave ameaça. Embriagar depois: <b>continua furto</b>.", lei:["157","157-1"] },
{ id:"fc26", tipo:"ce", sec:"roubo", f:"Certo ou errado: o roubo cometido com faca em 2025 tem a pena aumentada de 1/3 até metade.", v:"<b>Certo.</b> Art. 157, § 2º, VII (arma branca), em vigor desde 23/01/2020.", lei:["157-2"], j:["stj-t1110"] },
{ id:"fc27", tipo:"juris", sec:"roubo", f:"Roubo com concurso de pessoas e arma branca: o juiz pode aumentar de metade só porque há duas majorantes?", v:"<b>Não.</b> Súmula 443: exige fundamentação concreta; o número de majorantes não basta.", lei:["157-2"], j:["stj-s443"] },
{ id:"fc28", tipo:"numero", sec:"roubo", f:"Roubo de celular (fato de junho/2026): qual a consequência específica?", v:"Majorante de <b>1/3 até metade</b> (art. 157, § 2º, IX, Lei 15.397/2026). No furto, celular é qualificadora.", lei:["157-2"] },
{ id:"fc29", tipo:"caso", sec:"roubo", f:"Assalto com arma de brinquedo realista. Há roubo? Incide o aumento da arma de fogo? Cabe pena restritiva de direitos?", v:"Há <b>roubo</b> (grave ameaça); <b>não</b> incide a majorante; <b>não</b> cabe restritiva de direitos (Tema 1171).", lei:["157","157-2A"], j:["stj-t1171"] },
{ id:"fc30", tipo:"juris", sec:"roubo", f:"Para aplicar o +2/3 da arma de fogo é preciso apreender e periciar a arma?", v:"Pela JT 51, <b>não</b>, se o emprego for provado por outros meios; a defesa é quem prova a falta de potencial lesivo. O tema está afetado (Tema 1407).", lei:["157-2A"], j:["stj-jt51","stj-t1407"] },
{ id:"fc31", tipo:"numero", sec:"roubo", f:"Roubo com fuzil de uso restrito: qual a consequência?", v:"Pena do caput <b>em dobro</b> (art. 157, § 2º-B) — hediondo.", lei:["157-2B"] },
{ id:"fc32", tipo:"caso", sec:"roubo", f:"Subtração tentada + morte consumada da vítima. Qual o crime?", v:"<b>Latrocínio consumado</b> (Súmula 610 do STF).", lei:["157-3"], j:["stf-s610"] },
{ id:"fc33", tipo:"numero", sec:"roubo", f:"Latrocínio: pena atual e competência.", v:"<b>24 a 30 anos</b> e multa (Lei 15.397/2026); <b>juiz singular</b>, não o júri (Súmula 603 do STF).", lei:["157-3"], j:["stf-s603"] },
{ id:"fc34", tipo:"numero", sec:"roubo", f:"Latrocínio praticado por facção no contexto do grupo (157, § 5º): qual a pena? O que tem de curioso?", v:"<b>20 a 40 anos</b>. A mínima é menor que a do latrocínio comum (24), porque a Lei Antifacção veio antes da Lei 15.397.", lei:["157-4"] },
{ id:"fc35", tipo:"distincao", sec:"extorsao", f:"Roubo × extorsão: qual o critério decisivo?", v:"Na extorsão, a <b>colaboração da vítima é indispensável</b> (só ela pode realizar o ato). No roubo, o agente poderia tomar a coisa mesmo sem colaboração.", lei:["157","158"] },
{ id:"fc36", tipo:"caso", sec:"estelionato", f:"Golpista clona o WhatsApp de Pedro e pede R$ 500 à mãe dele, que faz o Pix. Qual o crime e a pena?", v:"<b>Fraude eletrônica</b> (171, § 2º-A): 4 a 8 anos. \"Duplicação de dispositivo eletrônico\" foi incluída em 2026.", lei:["171-2A"] },
{ id:"fc37", tipo:"juris", sec:"extorsao", f:"Extorsão é formal (Súmula 96). Ainda assim, cabe tentativa?", v:"<b>Sim</b>: se a vítima não pratica nenhuma conduta em resposta à ameaça (STJ, 3ª Seção, EAREsp 2.819.893-SP, 2026).", lei:["158"], j:["stj-s96","stj-inf895"] },
{ id:"fc38", tipo:"caso", sec:"extorsao", f:"Criminosos rendem a vítima e rodam com ela por caixas eletrônicos, sacando com o cartão dela. Qual o crime?", v:"<b>Extorsão com restrição da liberdade</b> — sequestro relâmpago (158, § 3º): 6 a 12 anos, hediondo.", lei:["158-3"] },
{ id:"fc39", tipo:"numero", sec:"extorsao", f:"Extorsão mediante sequestro: hipóteses do § 1º (12 a 20 anos).", v:"Sequestro por <b>mais de 24 horas</b>; vítima <b>menor de 18 ou maior de 60</b>; crime cometido por <b>bando ou quadrilha</b>.", lei:["159"] },
{ id:"fc40", tipo:"lacuna", sec:"extorsao", f:"Art. 159, § 4º: o concorrente que denunciar o crime à autoridade, ______, terá a pena reduzida de ______.", v:"<b>facilitando a libertação do sequestrado</b> · <b>um a dois terços</b>", lei:["159"] },
{ id:"fc41", tipo:"numero", sec:"usurpacao-dano", f:"Esbulho possessório (161, § 1º, II): qual o número mínimo de pessoas, se não houver violência ou grave ameaça?", v:"<b>Mais de duas</b> — ou seja, no mínimo três.", lei:["161"] },
{ id:"fc42", tipo:"numero", sec:"usurpacao-dano", f:"Em quais casos de dano a ação penal é privada?", v:"Dano <b>simples</b>; dano qualificado por <b>motivo egoístico ou prejuízo considerável</b>; e introdução de animais em propriedade alheia (art. 167).", lei:["163","167"] },
{ id:"fc43", tipo:"distincao", sec:"apropriacao", f:"Caixa da loja embolsa dinheiro aproveitando a distração do dono. Apropriação indébita ou furto?", v:"<b>Furto.</b> A apropriação indébita exige posse anterior <b>desvigiada</b>, fruto de confiança; o caixa tem mero contato vigiado.", lei:["168"] },
{ id:"fc44", tipo:"juris", sec:"apropriacao", f:"Apropriação indébita previdenciária: quando se consuma? Pagar extingue a punibilidade?", v:"Consuma-se com a <b>constituição definitiva do crédito</b> (Tema 1166). Pagar extingue, inclusive após a denúncia — <b>exceto</b> para o devedor contumaz (LC 225/2026).", lei:["168A"], j:["stj-t1166"] },
{ id:"fc45", tipo:"numero", sec:"apropriacao", f:"Apropriação de coisa achada: qual o prazo para devolver ou entregar à autoridade?", v:"<b>15 dias</b> (art. 169, parágrafo único, II).", lei:["169"] },
{ id:"fc46", tipo:"ce", sec:"gerais", f:"Certo ou errado: são hediondos o roubo com arma branca e o furto de celular.", v:"<b>Errado.</b> Hediondos patrimoniais: roubo com restrição de liberdade, com arma de fogo ou com lesão grave/morte; extorsão do 158, § 3º; extorsão mediante sequestro; furto com explosivo.", lei:["155-4A","157-2"] },
{ id:"fc47", tipo:"lacuna", sec:"estelionato", f:"Súmula 17 do STJ: \"Quando o falso se exaure no estelionato, ______, é por este absorvido.\"", v:"<b>sem mais potencialidade lesiva</b>", lei:["171"], j:["stj-s17"] },
{ id:"fc48", tipo:"caso", sec:"estelionato", f:"Cliente percebe, na hora, que o caixa errou e lhe deu R$ 80 de troco a mais, fica calado e vai embora. Qual o crime?", v:"<b>Estelionato</b> — manteve a vítima em erro pelo silêncio. Se só percebesse depois, em casa, seria apropriação de coisa havida por erro (169).", lei:["171","169"] },
{ id:"fc49", tipo:"juris", sec:"estelionato", f:"Cheque sem fundos: pagar antes ou depois do recebimento da denúncia muda o quê?", v:"<b>Antes</b>: impede a ação penal. <b>Depois</b>: não obsta o prosseguimento (Súmula 554 do STF).", lei:["171-2"], j:["stf-s554"] },
{ id:"fc50", tipo:"ce", sec:"estelionato", f:"Certo ou errado: emitir cheque pré-datado como garantia de dívida, que depois volta sem fundos, configura estelionato.", v:"<b>Errado.</b> Sem fraude não há crime (Súmula 246 do STF); cheque pré-datado em garantia não é ordem de pagamento à vista.", lei:["171-2"], j:["stf-s246"] },
{ id:"fc51", tipo:"caso", sec:"estelionato", f:"Sogra empresta a conta bancária ao genro golpista para receber e repassar valores dos golpes, sem ganhar nada. Comete crime?", v:"<b>Sim</b>: cessão de conta laranja (171, § 2º, VII — Lei 15.397/2026), mesmo cedendo gratuitamente.", lei:["171-2"] },
{ id:"fc52", tipo:"numero", sec:"estelionato", f:"Fraude eletrônica: pena e majorante do servidor no exterior.", v:"<b>4 a 8 anos</b> e multa; <b>+1/3 a 2/3</b> se usado servidor fora do território nacional.", lei:["171-2A"] },
{ id:"fc53", tipo:"numero", sec:"estelionato", f:"Estelionato contra idoso × contra entidade de direito público: frações.", v:"Idoso ou vulnerável: <b>1/3 até o dobro</b> (§ 4º). Entidade de direito público (ex.: INSS): <b>+1/3</b> (§ 3º).", lei:["171-3"] },
{ id:"fc54", tipo:"numero", sec:"estelionato", f:"Ação penal no estelionato: qual a regra para um golpe de março/2026? E de julho/2026?", v:"Março/2026: <b>condicionada à representação</b> (salvo exceções do antigo § 5º). Julho/2026: <b>incondicionada</b> — Lei 15.397 revogou o § 5º em 04/05/2026, sem retroagir.", lei:["171-5"], j:["stj-t1138"] },
{ id:"fc55", tipo:"numero", sec:"estelionato", f:"Art. 171-A (fraude com ativos virtuais): pena, natureza e benefícios.", v:"<b>4 a 8 anos</b>; crime <b>formal</b>; não cabe ANPP nem suspensão condicional do processo.", lei:["171A"] },
{ id:"fc56", tipo:"numero", sec:"receptacao", f:"Receptação simples: pena atual e consequência prática.", v:"<b>2 a 6 anos</b> (Lei 15.397/2026). Com mínima de 2 anos, <b>não cabe</b> suspensão condicional do processo.", lei:["180"] },
{ id:"fc57", tipo:"caso", sec:"receptacao", f:"Coautor do furto recebe sua parte dos objetos furtados. Responde também por receptação?", v:"<b>Não.</b> É pós-fato impunível; receptação só para quem não participou do crime anterior.", lei:["180"] },
{ id:"fc58", tipo:"distincao", sec:"receptacao", f:"Receptação simples × qualificada: o que muda no elemento subjetivo e no sujeito?", v:"Simples: coisa que <b>sabe</b> ser produto de crime (dolo direto), crime comum. Qualificada: coisa que <b>deve saber</b> (admite dolo eventual), por quem exerce atividade comercial ou industrial, inclusive clandestina ou em casa.", lei:["180","180-1"] },
{ id:"fc59", tipo:"ce", sec:"receptacao", f:"Certo ou errado: na receptação culposa, o juiz pode conceder perdão judicial ao réu primário.", v:"<b>Errado</b> para fatos a partir de 25/03/2026: o § 5º do art. 180 foi revogado pela Lei 15.358/2026.", lei:["180-3"] },
{ id:"fc60", tipo:"caso", sec:"receptacao", f:"Fazendeiro compra, para revender, cães de raça que deveria saber terem sido furtados. Qual o crime?", v:"<b>Receptação de animal</b> (180-A): 3 a 8 anos. Desde 2026 abrange animal doméstico, com finalidade de produção ou comercialização.", lei:["180A"] },
{ id:"fc61", tipo:"caso", sec:"gerais", f:"Filho e amigo furtam o relógio do pai do filho, de 56 anos. Quem responde? E se o pai tivesse 60?", v:"56 anos: filho <b>isento</b> (181, II); amigo <b>responde</b> (183, II). 60 anos: <b>ambos</b> respondem (183, III).", lei:["181","183"] },
{ id:"fc62", tipo:"caso", sec:"gerais", f:"Sobrinho furta o celular da tia, com quem não mora. A ação depende de representação?", v:"<b>Não.</b> O art. 182, III exige que o agente <b>coabite</b> com o tio ou sobrinho. Sem coabitação: ação incondicionada.", lei:["182"] }
];

