NEXO.questoes = [
{ id:"q-ef07", banca:"FGV", ano:2025, cargo:"Investigador de Polícia — PC/MG", sec:"roubo", gab:"E", fonteGab:"oficial",
  enun:"Em janeiro de 2025, no Município de Viçosa/MG, Jonas se aproximou de um transeunte e, mediante grave ameaça, consubstanciada no emprego de uma faca, determinou a entrega do seu telefone celular, sendo atendido. Em seguida, Jonas, na posse da res furtiva, correu, mas acabou sendo capturado em flagrante por um policial civil à paisana, três quarteirões depois. Sendo assim, a vítima logrou recuperar o bem móvel que havia sido levado. Nesse cenário, considerando as disposições do Código Penal, é correto afirmar que Jonas responderá pelo crime de",
  ops:["extorsão tentada, sem a incidência de causas de aumento de pena, pois o emprego de arma branca deixou de ser majorante no referido delito.","roubo tentado, sem a incidência de causas de aumento de pena, pois o emprego de arma branca deixou de ser majorante no referido delito.","extorsão consumada, com a incidência da causa de aumento de pena atrelada ao emprego de arma branca.","roubo tentado, com a incidência da causa de aumento de pena atrelada ao emprego de arma branca.","roubo consumado, com a incidência da causa de aumento de pena atrelada ao emprego de arma branca."],
  com:"Houve inversão da posse — consumado, mesmo com perseguição e recuperação (Súmula 582). A faca atrai o § 2º, VII (desde 2020). É roubo, não extorsão: a entrega era dispensável. Para fatos a partir de 04/05/2026, somaria também a majorante do celular (§ 2º, IX).",
  lei:["157","157-2"], j:["stj-s582"] },
{ id:"q-a688", banca:"Cebraspe", ano:2025, cargo:"Bloco comum", sec:"roubo", gab:"C", fonteGab:"oficial",
  enun:"O uso de um cabo de vassoura contra a vítima durante a prática de roubo pode justificar a aplicação da causa de aumento de pena prevista no art. 157, § 2.º, VII, do CP, desde que comprovada sua potencialidade lesiva, ainda que não haja perícia ou apreensão do objeto.",
  ops:["Certo","Errado"], com:"Arma branca abrange objetos aptos a ferir, inclusive os não fabricados para isso, se comprovada a potencialidade lesiva — prova que pode vir de outros meios.",
  lei:["157-2"] },
{ id:"q-3adc", banca:"FGV", ano:2022, cargo:"Perito Criminal — SEAD/AP", sec:"furto", gab:"D", fonteGab:"espelho",
  enun:"Em 03 de abril de 2022, Victor foi a um festival de música na cidade onde mora. Durante a madrugada, Victor percebeu que uma moradora de sua rua, Juliana, estava dançando distraída; Victor aproveitou o momento e subtraiu, sem violência ou grave ameaça, o smartphone de Juliana. Juliana somente percebeu que estava sem o aparelho celular quando chegou em casa e, no dia seguinte, realizou o registro de ocorrência. Em 05 de abril de 2022, Victor arrependeu-se, foi até a casa de Juliana, pediu desculpas e devolveu, intacto, o aparelho celular. Apesar disso, em 15 de abril de 2022, o Ministério Público denunciou Victor com incurso nas penas do Art. 155, caput, do CP. Na hipótese, é correto afirmar que",
  ops:["houve arrependimento eficaz, previsto no Art. 15, segunda parte, do CP, tendo em vista que Victor impediu a produção do resultado.","houve desistência voluntária, prevista no Art. 15, primeira parte, do CP, visto que Victor desistiu voluntariamente de seguir com a execução.","não houve crime, porque Victor se arrependeu e devolveu o bem intacto.","houve arrependimento posterior, previsto no Art. 16, do CP.","houve crime impossível, previsto no Art. 17, do CP."],
  com:"O furto já estava consumado; a devolução voluntária antes da denúncia, sem violência, gera arrependimento posterior (redução de 1/3 a 2/3). Hoje, o mesmo fato seria furto <b>qualificado</b> (celular, § 6º, II) e, sendo de madrugada, discutir-se-ia o repouso noturno — que não incide no qualificado (Tema 1087).",
  lei:["155","155-1"], alerta:"Gabarito de espelho. A lei mudou: em 2026 seria furto qualificado." },
{ id:"q-4f06", banca:"Cebraspe", ano:2025, cargo:"Bloco comum", sec:"furto", gab:"E", fonteGab:"oficial",
  enun:"Considere que um casal tenha sido preso em flagrante enquanto furtava cabos de energia elétrica em via pública: a mulher encontrava-se ao lado do poste de energia com uma mochila onde estavam armazenados diversos metros de fios já cortados e perto dela havia um facão utilizado para o corte; o homem se encontrava no alto do poste, com o facão em mãos, em plena retirada de novos cabos. Nessa situação, a ausência de laudo pericial sobre o local e os meios utilizados impede, em relação à mulher, a configuração da qualificadora da escalada no crime de furto, ainda que policiais tenham presenciado diretamente a prática delitiva e narrado detalhadamente os fatos.",
  ops:["Certo","Errado"], com:"O STJ dispensa a perícia da escalada quando os policiais presenciaram a execução. Além disso, as circunstâncias objetivas se comunicam à coautora. Hoje o fato também se enquadraria no § 8º (fios e cabos).",
  lei:["155-4","155-8"], j:["stj-escalada"] },
{ id:"q-9ae5", banca:"FGV", ano:2025, cargo:"Praças — PM/TO", sec:"gerais", gab:"E", fonteGab:"espelho",
  enun:"Lucas, policial militar no Estado do Tocantins, atuou em três diferentes prisões flagranciais durante seus plantões na primeira semana de março de 2025, envolvendo os seguintes delitos: I. Roubo circunstanciado pela restrição da liberdade da vítima. II. Posse de arma de fogo de uso proibido. III. Furto qualificado pelo emprego de explosivo. Nesse cenário, considerando as disposições da Lei nº 8.072/1990, é (são) crime(s) hediondo(s) o(s) elencado(s) em",
  ops:["I, apenas.","II, apenas.","III, apenas.","I e II, apenas.","I, II e III."],
  com:"Os três estão na Lei 8.072/90: roubo do 157, § 2º, V; posse ou porte de arma de uso proibido; furto do 155, § 4º-A.",
  lei:["155-4A","157-2"] },
{ id:"q-fd0f", banca:"FGV", ano:2025, cargo:"Perito Criminal — PC/MG", sec:"gerais", gab:"C", fonteGab:"oficial",
  enun:"Antônio, policial civil, está atuando em complexa investigação. Em razão dos reflexos práticos para o deslinde do procedimento investigatório, Antônio resolveu analisar a legislação que trata dos crimes hediondos, cotejando-a com os delitos que teriam sido praticados pelos investigados. Considerando as disposições da Lei nº 8.072/1990, avalie as afirmativas a seguir. I. Lesão corporal dolosa de natureza grave, em razão do perigo de vida, em detrimento de um policial civil no exercício das funções. II. Roubo circunstanciado pelo emprego de arma branca. III. Posse ilegal de arma de fogo de uso proibido. Assinale a opção que indica crimes hediondos.",
  ops:["I, apenas.","II, apenas.","III, apenas.","II e III, apenas.","I, II e III."],
  com:"Roubo com arma branca não é hediondo (só arma de fogo). Contra policial, a lei lista lesão gravíssima ou seguida de morte — perigo de vida é lesão grave. Resta só o III.",
  lei:["157-2"] },
{ id:"q-3349", banca:"Cebraspe", ano:2025, cargo:"Delegado de Polícia Federal", sec:"apropriacao", gab:"E", fonteGab:"oficial",
  enun:"A consumação do crime de apropriação indébita previdenciária prescinde da constituição definitiva, na via administrativa, do crédito tributário.",
  ops:["Certo","Errado"], com:"Errado: é crime material, consuma-se com a constituição definitiva do crédito (Tema 1166).", lei:["168A"], j:["stj-t1166"] },
{ id:"q-1210", banca:"Cebraspe", ano:2018, cargo:"Perito Criminal Federal", sec:"apropriacao", gab:"C", fonteGab:"oficial",
  enun:"Durante um ano e cinco meses, a empresa L&X recolheu as contribuições previdenciárias de seus empregados, mas não as repassou à previdência social, o que caracterizou o crime de apropriação indébita previdenciária. Nessa situação, se os representantes legais da empresa L&X, espontaneamente, confessarem e efetuarem o pagamento das contribuições antes do início da ação fiscal, ficará extinta a punibilidade.",
  ops:["Certo","Errado"], com:"Certo pelo § 2º. Ressalva de 2026: não vale para o devedor contumaz (LC 225/2026, § 5º).",
  lei:["168A"], alerta:"Hoje há exceção: devedor contumaz (LC 225/2026)." },
{ id:"q-b3cb", banca:"FGV", ano:2022, cargo:"Delegado de Polícia — PC/AM", sec:"apropriacao", gab:"D", fonteGab:"oficial",
  enun:"Quanto ao delito de apropriação indébita, em caso de bem de valor inferior a um salário mínimo e sendo primário o agente, é correto afirmar que",
  ops:["não há qualquer afetação da configuração do crime.","há expectativa ao reconhecimento da forma privilegiada.","há direito subjetivo à aplicação de atenuante obrigatória.","há direito subjetivo ao reconhecimento da forma privilegiada.","há incidência do princípio da insignificância."],
  com:"O art. 170 manda aplicar o privilégio do furto à apropriação indébita; presentes os requisitos, o réu tem direito subjetivo ao benefício.",
  lei:["168","169"] },
{ id:"q-3e08", banca:"Cebraspe", ano:2025, cargo:"Perito Criminal Federal — Contábil", sec:"estelionato", gab:"E", fonteGab:"oficial",
  enun:"Configura o crime de estelionato a conduta de praticar, antes ou depois da sentença que decretar a falência do empresário ou da sociedade empresária, ato fraudulento de que resulte ou possa resultar prejuízo aos credores, com o fim de obter ou assegurar vantagem indevida para si ou para outrem.",
  ops:["Certo","Errado"], com:"É crime falimentar (fraude a credores, Lei 11.101/2005, art. 168), norma especial. O estelionato é tipo genérico.", lei:["171"] },
{ id:"q-0c42", banca:"FGV", ano:2022, cargo:"Escrivão de Polícia — PC/AM", sec:"estelionato", gab:"B", fonteGab:"oficial",
  enun:"No dia 29 de junho de 2021, Maria, nascida em 20 de maio de 1944, foi vítima de um golpe, entregando a um estelionatário 10 mil reais, após ser induzida a erro pelo golpista. Hesita em procurar a polícia, mas o fato é comunicado à autoridade policial por uma vizinha da vítima. A propósito do início do inquérito policial que apura o crime de estelionato, no caso em questão, é correto afirmar que a autoridade policial",
  ops:["só pode instaurar inquérito se houver representação da ofendida, pois o crime em questão é de ação penal pública condicionada.","pode instaurar inquérito independentemente da representação da ofendida, pois o crime de estelionato praticado contra maior de 70 anos é de ação penal pública incondicionada.","pode instaurar inquérito sem a representação da ofendida, independentemente de sua idade, pois em qualquer caso a ação penal no crime de estelionato é pública incondicionada.","pode instaurar inquérito sem a representação da ofendida, pois qualquer investigação criminal pode ser iniciada de ofício pela autoridade policial, não se exigindo manifestação da vítima.","só pode instaurar inquérito se houver requerimento da ofendida, pois o crime em questão é de ação penal privada."],
  com:"Em 2021, a vítima tinha 77 anos: exceção do antigo § 5º, IV (maior de 70) — ação incondicionada. Atenção: para golpes a partir de 04/05/2026, a alternativa C passaria a ser a regra, porque o § 5º foi revogado.",
  lei:["171-5"], j:["stj-t1138"], alerta:"Correta pela lei de 2021. Para fatos a partir de 04/05/2026, a resposta mudaria." }
];

